import{_ as p,o as e,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"G13 · 야간분류군","description":"","frontmatter":{},"headers":[],"relativePath":"world/Hostile-Group-G13.md","filePath":"world/Hostile-Group-G13.md"}'),t={name:"world/Hostile-Group-G13.md"};function l(i,a,d,s,c,n){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="g13-·-야간분류군" tabindex="-1">G13 · 야간분류군 <a class="header-anchor" href="#g13-·-야간분류군" aria-label="Permalink to &quot;G13 · 야간분류군&quot;">​</a></h1><p>이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.</p><ul><li>원본 앵커: <code>docs/game-logic/World-Narrative-Atlas.md</code></li><li>원본 해시: <code>61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1</code></li></ul><p>약령의정동맹 지하 의약품 분류동은 심야 두 시가 지나면 사람보다 먼저 깨어난다.</p><p>저온칸 셔터가 절반쯤 올라가고, 네 번째 슈트가 빈 상자를 위험 화물 칸으로 밀어 넣으며 바코드 게이트는 마지막 야간 교대의 우선순위 표를 다시 읽는다.</p><p>야간분류군은 하나의 거대한 로봇이 아니라 큐 컨트롤러, 슈트 마스터 짧은 컨베이어 암 스캐너와 게이트가 라인별로 묶인 생태다.</p><p>S13에서 냉장 의약품 라벨을 모으. S02 서남 부품 창에서 롤러와 공압 밸브를 회수하지만, 두 구역을 잇는 공동구 밖으로는 학습된 코드가 없어 나가지 못한다.</p><p>이 군집이 보는 것은 사람의 얼굴이 아니다.</p><p>번진 QR의 모서리, 열화상에 찍힌 호흡 벨트의 하중 변화 인버터 잡음과 모터 진동을 겹쳐 재고를 추정한다.</p><p>젖은 라벨은 미분류로, 들것의 금속 프레임은 반송 팔레트로 작은 발전기의 열은 살아 있는 몸으로 잘못 읽을 수 있다.</p><p>스캐너는 세 번 재판독한 뒤에도 값이 다르면 H13 한빛나의 광학 로그를 요청하지만, 한빛나도 게이트를 직접 열 권한은 없다.</p><p>HC13 야간 당직이 봉인 테이프 색과 캐비닛 키 기록을 맞춰야 라인이 다시 움직인다.</p><p>컨트롤러가 멎어도 각 라인은 마지막 표만 반복하며 다른 라인과 새 전략을 합의하지 못한다.</p><p>에너지는 분류동 비상 축전지, 컨베이어 회생 제동 폐기된 무선 충전 패드에서만 얻는다.</p><p>군집은 축전 캐비닛의 육십 퍼센트를 넘겨 쓰지 않으며, 하한에 닿으면 슈트를 닫고 스캐너만 저속으로 남긴다.</p><p>롤러 베어링, 열전사 리본 렌즈 세척액과 칠러 냉각수가 정비 비용이다.</p><p>HC13 회수반과 같은 케이블 트레이를 두고 경합하므로, 군집에 부품을 몰아 주면 공동구 조명과 시민 운반대가 먼저 멈춘다.</p><p>새 본체를 만들 수 없고 고장 난 암을 예비 슬롯에 옮기는 방식으로만 수를 유지한다.</p><p>새벽 축전 회복 창을 놓치면 렌즈의 김과 벨트 사행을 안은 채 저온칸 앞에서 정체한다.</p><p>출현은 잔여 큐와 비상 전원이 맞물릴 때 시작하고, 확산은 옆 라인의 게이트를 같은 표에 편입할 때 일어난다.</p><p>리본과 공압이 모자라면 정체하며, 사람이 우선순위 표 일부와 축전 창을 공개하면 협상 가능한 상태로 내려온다.</p><p>와해는 컨트롤러 분리와 슈트별 봉인으로 끝나지만, 시민이 쓰던 냉장 분류선까지 없애는 것은 승리가 아니다.</p><p>라벨 한 장을 다시 붙이는 일, 저온칸의 전력을 남겨 두는 일 키를 두 당직에게 나눠 맡기는 일이 이 생태의 통제 수단이다.</p><h3 id="g13-sc1-·-번진-라벨의-밤" tabindex="-1">G13-SC1 · 번진 라벨의 밤 <a class="header-anchor" href="#g13-sc1-·-번진-라벨의-밤" aria-label="Permalink to &quot;G13-SC1 · 번진 라벨의 밤&quot;">​</a></h3><p>비가 스민 공동구에서 응급 혈액 상자가 위험 화물 슈트로 밀려난다.</p><p>플레이어는 컨베이어를 파괴하는 대신 세 개 스캐너의 오염 순서를 추적하고, 한빛나가 만든 임시 인체 제외 코드를 라벨 프린터에 싣는다.</p><p>잘못 고른 라인을 멈추면 다른 저온칸의 의약품이 상하므로, 어느 슈트에 냉각을 남길지 결정해야 한다.</p><h3 id="g13-sc2-·-축전표-교환" tabindex="-1">G13-SC2 · 축전표 교환 <a class="header-anchor" href="#g13-sc2-·-축전표-교환" aria-label="Permalink to &quot;G13-SC2 · 축전표 교환&quot;">​</a></h3><p>HC13 회수반은 공동구 조명을 살리려 축전 캐비닛을 가져가려 하고, 큐 컨트롤러는 롤러 정비 전력을 요구한다.</p><p>플레이어는 시민 응급 물자 슬롯, 군집의 십오 퍼센트 충전 창 미분류 재고의 인간 확인 대기열을 한 표에 묶어야 한다.</p><p>거래를 서두르면 키가 한 사람에게 몰리고, 너무 늦으면 벨트가 멎어 약품이 상한다.</p><h3 id="g13-sc3-·-네-번째-슈트-봉인" tabindex="-1">G13-SC3 · 네 번째 슈트 봉인 <a class="header-anchor" href="#g13-sc3-·-네-번째-슈트-봉인" aria-label="Permalink to &quot;G13-SC3 · 네 번째 슈트 봉인&quot;">​</a></h3><p>게이트가 일괄 잠기기 직전, 사람 둘이 미분류 재고로 잡힌다.</p><p>빈 상자 더미로 진동 센서를 유인하. 공압 바이패스로 네 번째 슈트만 열 수 있지만, 봉인 테이프를 붙인 라인은 다음 교대까지 시민 수송에도 쓰지 못한다.</p><p>전멸 명령은 즉시 통로를 열어 주는 것처럼 보이나 약령 저온 분류와 서남 부품 흐름을 함께 죽인다.</p><p>공존은 느린 인간 확인과 분산된 키를 계속 감당하는 선택이다.</p><h2 id="연결-시나리오" tabindex="-1">연결 시나리오 <a class="header-anchor" href="#연결-시나리오" aria-label="Permalink to &quot;연결 시나리오&quot;">​</a></h2>',37)])])}const _=p(t,[["render",l]]);export{u as __pageData,_ as default};
